<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {api,serviceMessage} from './api'
const props=defineProps({token:String,language:String})
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const cards=ref([]),name=ref(''),pin=ref(''),password=ref(''),waiting=ref(false),captured=ref(false),busy=ref(false),error=ref('')
const request=(path,options={})=>api('/api/owner/service-cards'+path,{token:props.token,...options})
async function load(){cards.value=(await request('')).cards}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false;password.value='';pin.value=''}}
async function enroll(){await request('/enroll',{method:'POST',body:JSON.stringify({name:name.value,pin:pin.value,password:password.value})});waiting.value=true;captured.value=false}
async function finish(){await request('/finish',{method:'POST'});waiting.value=false;name.value='';await load()}
async function cancel(){await request('/cancel',{method:'POST'});waiting.value=false;captured.value=false}
async function revoke(card){await request('/'+card.id,{method:'DELETE',body:JSON.stringify({password:password.value})});await load()}
let timer
onMounted(()=>{run(load);timer=setInterval(async()=>{if(!waiting.value||busy.value)return;try{const state=await request('/enrollment');waiting.value=state.waiting;captured.value=state.captured;error.value=state.error?serviceMessage(state.error):''}catch(e){error.value=e.message}},1000)})
onUnmounted(()=>{clearInterval(timer);if(waiting.value)request('/cancel',{method:'POST'}).catch(()=>{})})
</script>
<template><section class="card content"><h2>{{tr('Служебные карты Owner','Owner xizmat kartalari','Owner service cards')}}</h2><p>{{tr('Карты действуют на этом посту и не используются для оплаты. Обычную клиентскую карту без денег можно перевести в служебную. PIN: 4–12 цифр.','Kartalar shu postda ishlaydi, to‘lov uchun ishlatilmaydi. Pulsiz oddiy mijoz kartasini xizmat kartasiga o‘tkazish mumkin. PIN: 4–12 raqam.','Cards work on this station and cannot be used for payment. A customer card with no money can become a service card. PIN: 4–12 digits.')}}</p><p role="alert">{{error}}</p><form v-if="!waiting" class="fields" @submit.prevent="run(enroll)"><label>{{tr('Название карты','Karta nomi','Card name')}}<input v-model="name" maxlength="80" required /></label><label>PIN<input v-model="pin" type="password" inputmode="numeric" data-keyboard="pin" pattern="[0-9]{4,12}" minlength="4" maxlength="12" required autocomplete="new-password" /></label><label>{{tr('Пароль Owner','Owner paroli','Owner password')}}<input v-model="password" type="password" required autocomplete="current-password" /></label><button :disabled="busy" class="primary">{{tr('Добавить карту','Karta qo‘shish','Add card')}}</button></form><div v-else><p>{{captured?tr('Карта прочитана. Сохранить?','Karta o‘qildi. Saqlansinmi?','Card captured. Save?'):tr('Приложите новую или обычную клиентскую карту без денег в течение 60 секунд.','60 soniya ichida yangi yoki pulsiz oddiy mijoz kartasini qo‘ying.','Present a new card or a customer card with no money within 60 seconds.')}}</p><button v-if="captured" :disabled="busy" @click="run(finish)">{{tr('Сохранить','Saqlash','Save')}}</button><button :disabled="busy" @click="run(cancel)">{{tr('Отмена','Bekor qilish','Cancel')}}</button></div><ul><li v-for="card in cards" :key="card.id">{{card.name}} — {{card.active?tr('Активна','Faol','Active'):tr('Отозвана','Bekor qilingan','Revoked')}}<form v-if="card.active" @submit.prevent="run(()=>revoke(card))"><input v-model="password" type="password" :placeholder="tr('Пароль Owner для отзыва','Bekor qilish uchun Owner paroli','Owner password to revoke')" required autocomplete="current-password"/><button :disabled="busy">{{tr('Отозвать карту','Kartani bekor qilish','Revoke card')}}</button></form></li></ul></section></template>
